"use strict";(globalThis.webpackChunkgrc||=[]).push([[25228],{2200(e){e.exports=JSON.parse('{"citeKey":"sun2000statisticalempirical","slug":"sun-2000-statistical-empirical-eb77","title":"A Statistical-Empirical Hybrid Approach to Hierarchical Memory Analysis","authors":["X.-H. Sun","K. Cameron"],"venue":"The Euro-Par 2000, Lecture Notes in Computer Science 1900, Springer","type":"Conference","entryType":"inproceedings","date":"September, 2000","year":2000,"era":"iit","month":9,"doi":"10.1007/3-540-44520-x_18","abstract":"A hybrid approach that utilizes both statistical techniques and empirical methods seeks to provide more information about the per- formance of an application. In this paper, we present a general approach to creating hybrid models of this type. We show that for the scientific applications of interest, the scaled performance is somewhat predictable due to the regular characteristics of the measured codes. Furthermore, the resulting method encourages streamlined performance evaluation by determining which analysis steps may provide further insight to code performance.","hasAbstract":true,"lede":"We present a general approach to creating hybrid models of this type.","links":{"pdf":"https://grc.iit.edu/papers/2000/sun-2000-statistical-empirical-eb77.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);